<template><cl-crud ref="Crud"><cl-row><cl-refresh-btn/><cl-add-btn/><cl-flex1/></cl-row><cl-row><cl-table ref="Table"/></cl-row><cl-upsert ref="Upsert"/></cl-crud></template>
<script setup lang="ts">
import{useCrud,useTable,useUpsert}from'@cool-vue/crud';import{useCool}from'/@/cool';defineOptions({name:'loan-page-content'});const{service}=useCool();const Table=useTable({columns:[{label:'页面',prop:'title',minWidth:180},{label:'标识',prop:'key',width:130},{label:'版本',prop:'version',width:100},{label:'状态',prop:'status',width:90,dict:[{label:'停用',value:0,type:'danger'},{label:'启用',value:1,type:'success'}]},{label:'更新时间',prop:'updateTime',minWidth:170},{type:'op',buttons:['edit'],width:90}]});const Upsert=useUpsert({dialog:{width:'900px'},items:[{label:'页面标题',prop:'title',required:true,component:{name:'el-input'}},{label:'页面标识',prop:'key',required:true,component:{name:'el-input',props:{placeholder:'about / privacy'}}},{label:'版本',prop:'version',required:true,value:'1.0',component:{name:'el-input'}},{label:'页面内容',prop:'content',required:true,component:{name:'cl-editor',props:{name:'cl-editor-wang',height:430}}},{label:'状态',prop:'status',value:1,component:{name:'el-radio-group',options:[{label:'停用',value:0},{label:'启用',value:1}]}}]});const Crud=useCrud({service:(service as any).loan.pageContent},app=>app.refresh());
